### Contoh

Middleware autentikasi:

```js
function butuhLogin(req, res, next) {
  const [jenis, token] = (req.get('authorization') ?? '').split(' ');
  if (jenis !== 'Bearer' || !token) return res.status(401).json({ error: 'Perlu login' });
  try {
    const isi = jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] });
    req.pengguna = { id: Number(isi.sub), peran: isi.peran };
    next();
  } catch {
    res.status(401).json({ error: 'Token tidak valid atau kedaluwarsa' });
  }
}
```

Untuk email tidak terdaftar **dan** password salah, kirim pesan yang **sama**: `Email atau password salah`. Pesan yang berbeda memberi tahu penyerang email mana yang terdaftar.

