import express from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

const RAHASIA = 'kunci-rahasia-yang-panjang-dan-acak';
const pengguna = [{ id: 1, email: 'sari@toko.id', hashPassword: await bcrypt.hash('kopiSusu123', 10), peran: 'admin' }];
function butuhLogin(req, res, next) {
  const [jenis, token] = (req.get('authorization') ?? '').split(' ');
  if (jenis !== 'Bearer' || !token) return res.status(401).json({ error: 'Perlu login' });
  try {
    const isi = jwt.verify(token, RAHASIA, { algorithms: ['HS256'] });
    req.pengguna = { id: Number(isi.sub), peran: isi.peran };
    next();
  } catch {
    res.status(401).json({ error: 'Token tidak valid' });
  }
}
const app = express();
app.use(express.json());
app.post('/auth/masuk', async (req, res) => {
  const p = pengguna.find((x) => x.email === String(req.body.email).toLowerCase());
  const cocok = p && (await bcrypt.compare(String(req.body.password), p.hashPassword));
  if (!cocok) return res.status(401).json({ error: 'Email atau password salah' });
  res.json({ token: jwt.sign({ sub: String(p.id), peran: p.peran }, RAHASIA, { expiresIn: '15m' }) });
});
app.get('/saya', butuhLogin, (req, res) => res.json(req.pengguna));
const server = app.listen(3000);

const u = 'http://localhost:3000';
const masuk = (email, password) => fetch(u + '/auth/masuk', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) });
console.log((await (await masuk('rina@toko.id', 'apaSaja123')).json()).error);
console.log((await (await masuk('sari@toko.id', 'salah123')).json()).error);
const { token } = await (await masuk('SARI@toko.id', 'kopiSusu123')).json();
console.log((await fetch(u + '/saya')).status);
console.log(await (await fetch(u + '/saya', { headers: { Authorization: `Bearer ${token}` } })).json());
server.close();

