import express from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
const RAHASIA = 'kunci-toko-sari-yang-panjang';
const pengguna = [{ id: 1, email: 'rina@toko.id', hashPassword: await bcrypt.hash('rahasia123', 10) }];
const app = express();
app.use(express.json());
app.post('/auth/masuk', async (req, res) => {
  const p = pengguna.find((x) => x.email === req.body.email);
  if (!p || !(await bcrypt.compare(req.body.password, p.hashPassword))) return res.status(401).json({ error: 'Email atau password salah' });
  res.json({ token: jwt.sign({ sub: String(p.id) }, RAHASIA, { expiresIn: '15m' }) });
});
const server = app.listen(3000);
const r = await fetch('http://localhost:3000/auth/masuk', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: 'rina@toko.id', password: 'rahasia123' }) });
const { token } = await r.json();
console.log(r.status, token.split('.').length);
server.close();

