function ambilToken(header) {
  const [jenis, token] = (header ?? '').split(' ');
  if (jenis !== 'Bearer' || !token) return null;
  return token;
}
console.log(ambilToken('Bearer xyz'));
console.log(ambilToken('Token xyz'));
console.log(ambilToken(undefined));
